<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';learning_require_login();$pdo=learning_pdo();$uid=learning_user_id();$d=json_decode(file_get_contents('php://input'),true)?:[];$quiz=(int)($d['quiz_id']??0);$answers=$d['answers']??[];
try{$s=$pdo->prepare("SELECT * FROM learning_quizzes WHERE id=? AND is_published=1");$s->execute([$quiz]);$qz=$s->fetch();if(!$qz)throw new RuntimeException('Quiz not found');$s=$pdo->prepare("SELECT id,marks FROM learning_questions WHERE quiz_id=? ORDER BY sort_order");$s->execute([$quiz]);$qs=$s->fetchAll();$total=0;$score=0;$pdo->beginTransaction();$i=$pdo->prepare("INSERT INTO learning_quiz_attempts(user_id,quiz_id,total) VALUES(?,?,?)");$i->execute([$uid,$quiz,count($qs)]);$aid=(int)$pdo->lastInsertId();$ai=$pdo->prepare("INSERT INTO learning_quiz_answers(attempt_id,question_id,option_id,is_correct) VALUES(?,?,?,?)");foreach($qs as $q){$qid=(int)$q['id'];$oid=(int)($answers[(string)$qid]??0);$total+=(int)$q['marks'];$c=$pdo->prepare("SELECT is_correct FROM learning_options WHERE id=? AND question_id=?");$c->execute([$oid,$qid]);$ok=(int)($c->fetchColumn()??0);if($ok)$score+=(int)$q['marks'];$ai->execute([$aid,$qid,$oid?:null,$ok]);}$percent=$total?round($score*100/$total,2):0;$passed=$percent>=(int)$qz['pass_percent'];$xp=$passed?(int)$qz['xp']:0;$u=$pdo->prepare("UPDATE learning_quiz_attempts SET score=?,percent=?,passed=?,xp_earned=?,finished_at=NOW() WHERE id=?");$u->execute([$score,$percent,$passed?1:0,$xp,$aid]);$st=$pdo->prepare("INSERT INTO learning_user_stats(user_id,xp,quizzes_passed) VALUES(?,?,?) ON DUPLICATE KEY UPDATE xp=xp+VALUES(xp),quizzes_passed=quizzes_passed+VALUES(quizzes_passed)");$st->execute([$uid,$xp,$passed?1:0]);$pdo->commit();header('Content-Type:application/json');echo json_encode(['ok'=>true,'score'=>$score,'total'=>$total,'percent'=>$percent,'passed'=>$passed,'xp'=>$xp]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(500);header('Content-Type:application/json');echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}
